Reverse every word in a string.source:
import java.util.*;

public class Solution {
  public static String solve(String s) {
    String[] words = s.trim().split("\\s+");
    StringBuilder out = new StringBuilder();
    for (int i = words.length - 1; i >= 0; i--) {
      if (words[i].isEmpty()) continue;
      if (out.length() > 0) out.append(' ');
      out.append(words[i]);
    }
    return out.toString();
  }

  public static void main(String[] args) {
    System.out.println(solve("  the sky   is blue  "));
  }
}

Minimum number of bracket reversals to m.source:
import java.util.*;

public class Solution {
  public static int solve(String s) {
    if (s.length() % 2 == 1) return -1;
    int open = 0, close = 0;
    for (char c : s.toCharArray()) {
      if (c == '{') open++;
      else if (c == '}') {
        if (open > 0) open--;
        else close++;
      } else throw new IllegalArgumentException();
    }
    return (open + 1) / 2 + (close + 1) / 2;
  }

  public static void main(String[] args) {
    System.out.println(solve("}{{}}{{{"));
  }
}

Count and say.source:
import java.util.*;

public class Solution {
  public static String solve(int n) {
    if (n < 1) throw new IllegalArgumentException();
    String s = "1";
    for (int step = 1; step < n; step++) {
      StringBuilder next = new StringBuilder();
      for (int i = 0; i < s.length(); ) {
        int j = i + 1;
        while (j < s.length() && s.charAt(j) == s.charAt(i)) j++;
        next.append(j - i).append(s.charAt(i));
        i = j;
      }
      s = next.toString();
    }
    return s;
  }

  public static void main(String[] args) {
    System.out.println(solve(5));
  }
}

Rabin Karp Algorithm.source:
import java.util.*;

public class Solution {
  public static List<Integer> solve(String text, String pattern) {
    final long mod = 1000000007L, base = 257;
    int n = text.length(), m = pattern.length();
    List<Integer> out = new ArrayList<>();
    if (m > n) return out;
    if (m == 0) {
      for (int i = 0; i <= n; i++) out.add(i);
      return out;
    }
    long high = 1, wanted = 0, current = 0;
    for (int i = 0; i < m; i++) {
      wanted = (wanted * base + pattern.charAt(i)) % mod;
      current = (current * base + text.charAt(i)) % mod;
      if (i < m - 1) high = high * base % mod;
    }
    for (int i = 0; i <= n - m; i++) {
      if (current == wanted && text.regionMatches(i, pattern, 0, m)) out.add(i);
      if (i < n - m) {
        current = (current - text.charAt(i) * high % mod + mod) % mod;
        current = (current * base + text.charAt(i + m)) % mod;
      }
    }
    return out;
  }

  public static void main(String[] args) {
    System.out.println(solve("ababa", "aba"));
  }
}

Z function.source:
import java.util.*;

public class Solution {
  public static int[] solve(String s) {
    int[] z = new int[s.length()];
    int l = 0, r = 0;
    for (int i = 1; i < s.length(); i++) {
      if (i <= r) z[i] = Math.min(r - i + 1, z[i - l]);
      while (i + z[i] < s.length() && s.charAt(z[i]) == s.charAt(i + z[i])) z[i]++;
      if (i + z[i] - 1 > r) {
        l = i;
        r = i + z[i] - 1;
      }
    }
    return z;
  }

  public static void main(String[] args) {
    System.out.println(Arrays.toString(solve("aaaaa")));
  }
}

KMP Algorithm or LPS array.source:
import java.util.*;

public class Solution {
  public static int[] lps(String s) {
    int[] a = new int[s.length()];
    for (int i = 1, len = 0; i < s.length(); ) {
      if (s.charAt(i) == s.charAt(len)) a[i++] = ++len;
      else if (len > 0) len = a[len - 1];
      else a[i++] = 0;
    }
    return a;
  }

  public static List<Integer> solve(String text, String pattern) {
    List<Integer> out = new ArrayList<>();
    if (pattern.isEmpty()) {
      for (int i = 0; i <= text.length(); i++) out.add(i);
      return out;
    }
    int[] fail = lps(pattern);
    for (int i = 0, j = 0; i < text.length(); ) {
      if (text.charAt(i) == pattern.charAt(j)) {
        i++;
        j++;
        if (j == pattern.length()) {
          out.add(i - j);
          j = fail[j - 1];
        }
      } else if (j > 0) j = fail[j - 1];
      else i++;
    }
    return out;
  }

  public static void main(String[] args) {
    System.out.println(solve("ababa", "aba"));
  }
}

Shortest Palindrome.source:
import java.util.*;

public class Solution {
  public static String solve(String s) {
    int[] a = new int[2 * s.length() + 1];
    for (int i = 0; i < s.length(); i++) a[i] = s.charAt(i);
    a[s.length()] = -1;
    for (int i = 0; i < s.length(); i++) a[s.length() + 1 + i] = s.charAt(s.length() - 1 - i);
    int[] fail = new int[a.length];
    for (int i = 1, j = 0; i < a.length; i++) {
      while (j > 0 && a[i] != a[j]) j = fail[j - 1];
      if (a[i] == a[j]) j++;
      fail[i] = j;
    }
    int palindrome = fail[a.length - 1];
    return new StringBuilder(s.substring(palindrome)).reverse().append(s).toString();
  }

  public static void main(String[] args) {
    System.out.println(solve("aacecaaa"));
  }
}

Longest happy prefix.source:
import java.util.*;

public class Solution {
  public static int[] lps(String s) {
    int[] a = new int[s.length()];
    for (int i = 1, len = 0; i < s.length(); ) {
      if (s.charAt(i) == s.charAt(len)) a[i++] = ++len;
      else if (len > 0) len = a[len - 1];
      else a[i++] = 0;
    }
    return a;
  }

  public static String solve(String s) {
    return s.isEmpty() ? "" : s.substring(0, lps(s)[s.length() - 1]);
  }

  public static void main(String[] args) {
    System.out.println(solve("level"));
  }
}
